 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def edge_runs(row):
        runs = []
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            color, start = row[c], c
            while c < w and row[c] == color:
                c += 1
            runs.append((start, c, color))
        return runs

    upper, lower = edge_runs(grid[0]), edge_runs(grid[-1])
    if not upper or not lower:
        return out
    top_start, _, _ = upper[0]
    bottom_start, _, _ = lower[-1]
    shift = bottom_start - top_start

    for r in range(1, h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            out[r][c] = 4
            for y in range(1, r):
                out[y][c] = color
            target = c + shift
            if 0 <= target < w:
                for y in range(0, h - 1):
